import{_ as p,r as n,o,c as l,e,a as i,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Updating Partials - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Pulling partial updates","slug":"pulling-partial-updates","link":"#pulling-partial-updates","children":[{"level":3,"title":"Update definition","slug":"update-definition","link":"#update-definition","children":[]},{"level":3,"title":"Appending and prepending content","slug":"appending-and-prepending-content","link":"#appending-and-prepending-content","children":[]}]},{"level":2,"title":"Pushing partial updates","slug":"pushing-partial-updates","link":"#pushing-partial-updates","children":[]},{"level":2,"title":"Passing variables to partials","slug":"passing-variables-to-partials","link":"#passing-variables-to-partials","children":[]}],"relativePath":"1.x/ajax/update-partials.md","filePath":"1.x/ajax/update-partials.md"}'),c={name:"1.x/ajax/update-partials.md"};function d(u,a,g,h,k,m){const s=n("pre-heading"),t=n("post-heading");return o(),l("div",null,[e(s),a[0]||(a[0]=i("h1",null,"Updating Partials",-1)),e(t),a[1]||(a[1]=r(`<p>When a handler executes it may prepare partials that are updated on the page, either by pushing or pulling, which can be rendered with some supplied variables.</p><h2 id="pulling-partial-updates"><a href="#pulling-partial-updates" class="header-anchor">#</a> Pulling partial updates</h2><p>The client browser may request partials to be updated from the server when it performs an AJAX request, which is considered <em>pulling a content update</em>. The following code renders the <strong>mytime</strong> partial inside the <code>#myDiv</code> element on the page after calling the <code>onRefreshTime</code> <a href="./../ajax/handlers.html">event handler</a>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>mytime<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The <a href="./../ajax/attributes-api.html">data attributes API</a> uses the <code>data-request-update</code> attribute.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Attributes API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefreshTime<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mytime: &#39;#myDiv&#39;<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Go
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The <a href="./../ajax/javascript-api.html">JavaScript API</a> uses the <code>update</code> configuration option:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token comment">// JavaScript API</span>
$<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onRefreshTime&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">update</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">mytime</span><span class="token operator">:</span> <span class="token string">&#39;#myDiv&#39;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="update-definition"><a href="#update-definition" class="header-anchor">#</a> Update definition</h3><p>The definition of what should be updated is specified as a JSON-like object where:</p><ul><li>the left side (key) is the <strong>partial name</strong></li><li>the right side (value) is the <strong>target element</strong> to update</li></ul><p>The following will request to update the <code>#myDiv</code> element with <strong>mypartial</strong> contents.</p><div class="language- extra-class"><pre class="language-text"><code>mypartial: &#39;#myDiv&#39;
</code></pre></div><p>Multiple partials are separated by commas.</p><div class="language- extra-class"><pre class="language-text"><code>firstpartial: &#39;#myDiv&#39;, secondpartial: &#39;#otherDiv&#39;
</code></pre></div><p>If the partial name contains a slash or a dash, it is important to &#39;quote&#39; the left side.</p><div class="language- extra-class"><pre class="language-text"><code>&#39;folder/mypartial&#39;: &#39;#myDiv&#39;, &#39;my-partial&#39;: &#39;#myDiv&#39;
</code></pre></div><p>The target element will always be on the right side since it can also be a HTML element in JavaScript.</p><div class="language- extra-class"><pre class="language-text"><code>mypartial: document.getElementById(&#39;myDiv&#39;)
</code></pre></div><h3 id="appending-and-prepending-content"><a href="#appending-and-prepending-content" class="header-anchor">#</a> Appending and prepending content</h3><p>If the selector string is prepended with the <code>@</code> symbol, the content received from the server will be appended to the element, instead of replacing the existing content.</p><div class="language- extra-class"><pre class="language-text"><code>&#39;folder/append&#39;: &#39;@#myDiv&#39;
</code></pre></div><p>If the selector string is prepended with the <code>^</code> symbol, the content will be prepended instead.</p><div class="language- extra-class"><pre class="language-text"><code>&#39;folder/append&#39;: &#39;^#myDiv&#39;
</code></pre></div><h2 id="pushing-partial-updates"><a href="#pushing-partial-updates" class="header-anchor">#</a> Pushing partial updates</h2><p>Comparatively, <a href="./../ajax/handlers.html">AJAX handlers</a> can <em>push content updates</em> to the client-side browser from the server-side. To push an update the handler returns an array where the key is a HTML element to update (using a simple CSS selector) and the value is the content to update.</p><p>The following example will update an element on the page with the id <strong>myDiv</strong> using the contents found inside the partial <strong>mypartial</strong>. The <code>onRefreshTime</code> handler calls the <code>renderPartial</code> method to render the partial contents in PHP.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRefreshTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;#myDiv&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;mypartial&#39;</span><span class="token punctuation">)</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>Note:</strong> The key name must start with an identifier <code>#</code> or class <code>.</code> character to trigger a content update.</p></blockquote><h2 id="passing-variables-to-partials"><a href="#passing-variables-to-partials" class="header-anchor">#</a> Passing variables to partials</h2><p>Depending on the execution context, an <a href="./../ajax/handlers.html">AJAX event handler</a> makes variables available to partials differently.</p><ul><li>Use <code>$this[]</code> inside a page or layout <a href="./../cms/themes.html#php-section">PHP section</a>.</li><li>Use <code>$this-&gt;page[]</code> inside a <a href="./../plugin/components.html#ajax-handlers">component class</a>.</li><li>Use <code>$this-&gt;vars[]</code> in the <a href="./../backend/controllers-ajax.html#using-ajax-handlers">back-end area</a>.</li></ul><p>These examples will provide the <strong>result</strong> variable to a partial for each context:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// From page or layout PHP code section</span>
<span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// From a component class</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>

<span class="token comment">// From a backend controller or widget</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Hello world!&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>This value can then be accessed using Twig in the partial:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- Hello world! --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span>
</code></pre></div>`,36))])}const y=p(c,[["render",d]]);export{f as __pageData,y as default};
